using Bim.Cad;
using System.Diagnostics;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

// P6-18 PDF simple-font /Encoding /Differences oracle. The committed fixture differences.pdf (stdlib generator
// differences-pdf.py, bytes pinned here and regenerated byte for byte on Linux/macOS) shows room labels with three simple
// fonts that have no ToUnicode CMap, only an /Encoding dictionary: a TrueType subset over /StandardEncoding whose codes
// 1..12 are named by /Differences (uni00B2 included), a Type1 font over /WinAnsiEncoding (indirect encoding object) with
// ñ and ² at codes 128 and 129, and a Type1 font over /MacRomanEncoding with ² at code 1. The strings decode to Unicode
// and BriefExtract reads the rooms, "Baño" included. Generated pages then pin each base encoding, the glyph-name forms
// (Latin names, uniXXXX and its sequences, uXXXX..uXXXXXX, a .suffix), unknown names (afii, lower-case or surrogate uni,
// out of range: today's byte decoding with encoding-glyph-unknown on the showing operator), out-of-range /Differences
// codes, name-only encodings (today's decoding), and ToUnicode winning over the encoding. Unit-tested evidence only.
internal static class PdfEncodingTests
{
    private static string I(long value) => value.ToString(CultureInfo.InvariantCulture);
    private static byte[] L(string text) => Encoding.Latin1.GetBytes(text);
    private static string Warnings(PdfDocument document) => string.Join(";", document.Warnings.Select(w => w.Code + "@" + I(w.Page) + ":" + I(w.ObjectNumber) + ":" + I(w.OperatorIndex)));
    private static string Escape(string text) => string.Concat(text.Select(c => c < 0x20 || c > 0x7E ? "\\u" + ((int)c).ToString("X4", CultureInfo.InvariantCulture) : c.ToString()));
    private static string Texts(PdfDocument document) => string.Join("|", document.Pages.SelectMany(p => p.Elements).OfType<PdfText>().Select(t => Escape(t.Value)));

    private static string Font(string encoding, bool toUnicode = false) =>
        "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding " + encoding + (toUnicode ? " /ToUnicode 6 0 R" : "") + " >>";

    private static string Show(string literal) => "BT /F1 10 Tf 1 0 0 1 50 50 Tm (" + literal + ") Tj ET";

    private static PdfDocument Page(string content, string font, params (int Number, byte[] Body)[] extra) =>
        PdfReader.Parse(PdfToUnicodeTests.PageBytes(content, font, null, "", null, extra), "encoding-gen.pdf");

    private static PdfDocument Page2(string content, string font, string font2) =>
        PdfReader.Parse(PdfToUnicodeTests.PageBytes(content, font, null, "", font2), "encoding-gen.pdf");

    public static void Run(Action<bool, string, string> check, string fixtures)
    {
        void C(bool condition, string name, string detail = "") => check(condition, "encoding " + name, detail);

        // ---------- committed fixture ----------
        try
        {
            var path = Path.Combine(fixtures, "differences.pdf");
            var bytes = File.ReadAllBytes(path);
            var sha = Convert.ToHexString(SHA256.HashData(bytes));
            C(sha == "70BE384DD7EA6239C1E06952DF737C5EC6C3A001E69A74BB7C4D3891695A4168", "fixture bytes equal the committed generator output", sha);
            if (!OperatingSystem.IsWindows())
            {
                var regenerated = Path.Combine(Path.GetTempPath(), "bim-p6-18-" + Guid.NewGuid().ToString("N", CultureInfo.InvariantCulture) + ".pdf");
                try
                {
                    var start = new ProcessStartInfo("python3") { UseShellExecute = false, RedirectStandardError = true, RedirectStandardOutput = true };
                    foreach (var argument in new[] { "-I", Path.Combine(fixtures, "differences-pdf.py"), regenerated }) start.ArgumentList.Add(argument);
                    using var process = Process.Start(start)!;
                    var error = process.StandardError.ReadToEnd();
                    process.StandardOutput.ReadToEnd();
                    process.WaitForExit();
                    var again = File.Exists(regenerated) ? File.ReadAllBytes(regenerated) : Array.Empty<byte>();
                    C(process.ExitCode == 0 && again.SequenceEqual(bytes), "differences-pdf.py rewrites differences.pdf byte for byte",
                        "exit " + I(process.ExitCode) + " " + error + " sha256 " + Convert.ToHexString(SHA256.HashData(again)));
                }
                catch (System.ComponentModel.Win32Exception missing)
                {
                    // python3 is installed on the Linux CI runners; elsewhere a missing interpreter only skips the rerun.
                    C(!(OperatingSystem.IsLinux() && Environment.GetEnvironmentVariable("GITHUB_ACTIONS") == "true"), "python3 is available on Linux CI to rerun the generator", missing.Message);
                }
                finally
                {
                    if (File.Exists(regenerated)) File.Delete(regenerated);
                }
            }

            var document = PdfReader.ReadFile(path);
            C(document.Warnings.Count == 0, "fixture reads without warnings", Warnings(document));
            var texts = document.Pages[0].Elements.OfType<PdfText>().ToList();
            C(Texts(document) == "Dormitorio 1|12,00 m\\u00B2|Ba\\u00F1o|4,00 m\\u00B2|Cocina|9,00 m\\u00B2", "fixture /Differences glyph names over Standard, WinAnsi and MacRoman decode to Unicode", Texts(document));
            C(string.Join(",", texts.Select(t => t.FontName + ":" + t.Provenance.Operator + I(t.Provenance.OperatorIndex))) == "F3:Tj22,F3:Tj27,F1:Tj32,F1:TJ37,F2:Tj42,F2:Tj47",
                "fixture text fonts and showing operators keep their provenance", string.Join(",", texts.Select(t => t.FontName + ":" + t.Provenance.Operator + I(t.Provenance.OperatorIndex))));

            var draft = BriefExtract.FromPdf(document, 1, null, new BriefExtractOptions { MetresPerUnit = 0.02 });
            var ids = string.Join(",", draft.Rooms.Select(r => r.Id).OrderBy(id => id, StringComparer.Ordinal));
            C(ids == "bano,cocina,dormitorio-1", "brief extraction reads the three room labels", ids + " " + string.Join(",", draft.Uncertainties.Select(u => u.Code)));
            var bano = draft.Rooms.FirstOrDefault(r => r.Id == "bano");
            var bed = draft.Rooms.FirstOrDefault(r => r.Id == "dormitorio-1");
            var kitchen = draft.Rooms.FirstOrDefault(r => r.Id == "cocina");
            C(bano is not null && bano.Name == "Baño" && bano.StatedAreaSquareMetres is { } a && Math.Abs(a - 4) < 1e-9
                && bed is not null && bed.Name == "Dormitorio 1" && bed.StatedAreaSquareMetres is { } b && Math.Abs(b - 12) < 1e-9
                && kitchen is not null && kitchen.Name == "Cocina" && kitchen.StatedAreaSquareMetres is { } k && Math.Abs(k - 9) < 1e-9,
                "Baño, Dormitorio 1 and Cocina carry their names and stated areas", (bano?.ToString() ?? "null") + " " + (bed?.ToString() ?? "null") + " " + (kitchen?.ToString() ?? "null"));
            C(!draft.Uncertainties.Any(u => u.Code is "orphan-area" or "unlabelled-region" or "uncalibrated") && draft.Issues.Count == 0,
                "every area text pairs with a label and every region is a room", string.Join(",", draft.Uncertainties.Select(u => u.Code)));
        }
        catch (Exception error) { C(false, "fixture unexpected", error.GetType().Name + ": " + error.Message); }

        // ---------- existing fixtures have no encoding warning ----------
        try
        {
            foreach (var name in new[] { "simple-plan.pdf", "transforms.pdf", "flate.pdf", "draft-plan.pdf", "brief-plan.pdf", "brief-plan-xobject.pdf", "tounicode.pdf" })
            {
                var document = PdfReader.ReadFile(Path.Combine(fixtures, name));
                C(!document.Warnings.Any(w => w.Code.StartsWith("encoding", StringComparison.Ordinal)), name + " has no encoding warning", Warnings(document));
            }
        }
        catch (Exception error) { C(false, "existing fixtures unexpected", error.GetType().Name + ": " + error.Message); }

        // ---------- base encodings under /Differences ----------
        try
        {
            var win = Page(Show("\\200AB\\223\\201"), Font("<< /BaseEncoding /WinAnsiEncoding /Differences [65 /eacute] >>"));
            C(Texts(win) == "\\u20AC\\u00E9B\\u201C\\u0081" && win.Warnings.Count == 0, "WinAnsi base: Euro and quotedblleft from the base, a Differences override, an undefined code stays Latin-1",
                Texts(win) + " " + Warnings(win));
            var mac = Page(Show("\\001\\204\\226\\216\\325"), Font("<< /BaseEncoding /MacRomanEncoding /Differences [1 /uni00D1] >>"));
            C(Texts(mac) == "\\u00D1\\u00D1\\u00F1\\u00E9\\u2019" && mac.Warnings.Count == 0, "MacRoman base: Ntilde, ntilde, eacute and quoteright from the base", Texts(mac) + " " + Warnings(mac));
            var standard = Page(Show("\\001'`\\341\\373\\244"), Font("<< /BaseEncoding /StandardEncoding /Differences [1 /Lslash] >>"));
            C(Texts(standard) == "\\u0141\\u2019\\u2018\\u00C6\\u00DF\\u2044" && standard.Warnings.Count == 0, "Standard base: quoteright, quoteleft, AE, germandbls and fraction from the base",
                Texts(standard) + " " + Warnings(standard));
            var none = Page(Show("\\001A\\351\\200"), Font("<< /Type /Encoding /Differences [1 /ntilde] >>"));
            C(Texts(none) == "\\u00F1A\\u00E9\\u0080" && none.Warnings.Count == 0, "without /BaseEncoding codes outside /Differences keep today's Latin-1", Texts(none) + " " + Warnings(none));
            var indirect = Page(Show("Ba\\200o"), Font("8 0 R"), (8, L("<< /Type /Encoding /BaseEncoding /WinAnsiEncoding /Differences [128 /ntilde] >>")));
            C(Texts(indirect) == "Ba\\u00F1o" && indirect.Warnings.Count == 0, "an indirect /Encoding dictionary is read", Texts(indirect) + " " + Warnings(indirect));
            var named = Page2(Show("\\200\\001") + " BT /F2 10 Tf 1 0 0 1 50 50 Tm (\\226) Tj ET", Font("/WinAnsiEncoding"), Font("/MacRomanEncoding"));
            C(Texts(named) == "\\u0080\\u0001|\\u0096" && named.Warnings.Count == 0, "an /Encoding name without a dictionary keeps today's decoding", Texts(named) + " " + Warnings(named));
            var bounds = Page(Show("\\377\\002B\\003"), Font("<< /BaseEncoding /WinAnsiEncoding /Differences [255 /a /b 300 /c -1 /d 2.5 /e 66 /Euro] >>"));
            C(Texts(bounds) == "a\\u0002\\u20AC\\u0003" && bounds.Warnings.Count == 0, "Differences codes past 255, negative or non-integer are ignored", Texts(bounds) + " " + Warnings(bounds));
        }
        catch (Exception error) { C(false, "base unexpected", error.GetType().Name + ": " + error.Message); }

        // ---------- glyph names ----------
        try
        {
            var names = Page(Show("\\001\\002\\003\\004\\005\\006\\007\\010\\011\\012"),
                Font("<< /Differences [1 /uni00F1 /uni20AC /u1F600 /eacute.sc /uni004100420043 /Euro /quoteright /germandbls /Lslash /fi] >>"));
            C(Texts(names) == "\\u00F1\\u20AC\\uD83D\\uDE00\\u00E9ABC\\u20AC\\u2019\\u00DF\\u0141\\uFB01" && names.Warnings.Count == 0,
                "uniXXXX, uniXXXX sequences, uXXXXX, a .suffix and Latin glyph names map to Unicode", Texts(names) + " " + Warnings(names));
            var latin = Page(Show("\\001\\002\\003\\004\\005\\006\\007\\010\\011\\012\\013\\014"),
                Font("<< /Differences [1 /aacute /eacute /iacute /oacute /uacute /ntilde /Aacute /Eacute /Iacute /Oacute /Uacute /Ntilde] >>"));
            C(Texts(latin) == "\\u00E1\\u00E9\\u00ED\\u00F3\\u00FA\\u00F1\\u00C1\\u00C9\\u00CD\\u00D3\\u00DA\\u00D1" && latin.Warnings.Count == 0, "Spanish accented glyph names map to Unicode",
                Texts(latin) + " " + Warnings(latin));

            var unknown = Page("BT /F1 10 Tf 1 0 0 1 50 50 Tm (\\001\\002) Tj (\\006A) Tj [(\\003) -300 (\\004\\005)] TJ (\\006) Tj ET",
                Font("<< /BaseEncoding /WinAnsiEncoding /Differences [1 /foo /afii10017 /uniD800 /uni00f1 /u110000 /ntilde 65 /bar] >>"));
            C(Texts(unknown) == "\\u0001\\u0002|\\u00F1A|\\u0003 \\u0004\\u0005|\\u00F1", "unknown glyph names (afii, surrogate or lower-case uni, past U+10FFFF) keep today's byte decoding",
                Texts(unknown));
            C(Warnings(unknown) == "encoding-glyph-unknown@1:4:3;encoding-glyph-unknown@1:4:4;encoding-glyph-unknown@1:4:5", "each show of an unknown glyph name warns encoding-glyph-unknown",
                Warnings(unknown));
            C(unknown.Warnings.Count > 0 && unknown.Warnings[0].Message.Contains("/foo", StringComparison.Ordinal) && unknown.Warnings[0].Message.Contains("/F1", StringComparison.Ordinal),
                "the warning names the glyph and the font", unknown.Warnings.Count > 0 ? unknown.Warnings[0].Message : "none");
        }
        catch (Exception error) { C(false, "names unexpected", error.GetType().Name + ": " + error.Message); }

        // ---------- ToUnicode still wins ----------
        try
        {
            var cmap = PdfToUnicodeTests.CMap("2 beginbfchar\n<01> <0058>\n<03> <0059>\nendbfchar", "<00> <FF>");
            var both = PdfToUnicodeTests.Page(Show("\\001\\002\\003"), Font("<< /Differences [1 /ntilde /eacute /foo] >>", toUnicode: true), cmap);
            C(Texts(both) == "X\\u00E9Y" && both.Warnings.Count == 0, "ToUnicode wins over /Differences; codes it does not map use the encoding", Texts(both) + " " + Warnings(both));
            var invalid = PdfToUnicodeTests.Page(Show("\\001"), Font("<< /Differences [1 /ntilde] >>", toUnicode: true), PdfToUnicodeTests.CMap("", "<00> <FF>"));
            C(Texts(invalid) == "\\u00F1" && Warnings(invalid) == "tounicode-invalid@1:4:1", "an unusable ToUnicode CMap warns and the encoding applies", Texts(invalid) + " " + Warnings(invalid));
        }
        catch (Exception error) { C(false, "tounicode unexpected", error.GetType().Name + ": " + error.Message); }
    }
}
